steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        comments(limit: 100) {
          nodes {
            id
            body
            createdAt
            issue {
              id
              identifier
              title
            }
            user {
              id
              name
              email
            }
            replies {
              nodes {
                id
                body
                createdAt
                user {
                  id
                  name
                  email
                }
              }
            }
          }
        }
      }
    '
  }'
